parameters.jsCode:
// DataForSEO answers a bad filter, an empty account and an unsupported target
// with HTTP 200 and the failure inside the body, so the task's own status_code
// is the only thing worth trusting.
const cfg = $('Settings').first().json;
// single-item input: the node above is one API call, so one response item.
const payload = $input.first().json || {};
const task = ((payload.tasks || [])[0]) || {};

if (Number(task.status_code) !== 20000) {
  return [{
    json: {
      failed: true,
      reason: String(task.status_message || 'DataForSEO returned no task'),
      links: [],
      total_lost: 0,
      window_days: Number(cfg.lost_since_days) || 30,
    },
  }];
}

const result = ((task.result || [])[0]) || {};
const items = Array.isArray(result.items) ? result.items : [];
const totalLost = Number(result.total_count) || 0;

const maxSpam = Number(cfg.max_spam_score);
const minRank = Number(cfg.min_rank) || 0;

// One row per referring domain. A domain that linked from forty pages is one
// conversation, not forty, and leaving the duplicates in means the top of the
// list is a single site repeated.
const best = new Map();
for (const row of items) {
  const domain = String(row.domain_from || '').toLowerCase();
  if (!domain) continue;
  const rank = Number(row.rank) || 0;
  if (rank < minRank) continue;
  if (Number.isFinite(maxSpam) && Number(row.backlink_spam_score) > maxSpam) continue;

  const seen = best.get(domain);
  if (!seen || rank > seen.rank) {
    best.set(domain, {
      link_id: `${domain}|${String(row.url_to || '')}`,
      domain_from: domain,
      url_from: String(row.url_from || ''),
      url_to: String(row.url_to || ''),
      anchor: row.anchor === null || row.anchor === undefined ? '' : String(row.anchor),
      rank,
      domain_rank: Number(row.domain_from_rank) || 0,
      dofollow: row.dofollow === true,
      item_type: String(row.item_type || 'anchor'),
      // Both of these are from DataForSEO's crawl, not from now. Our own side
      // gets re-checked live further down; theirs is reported as-crawled.
      url_to_status_crawled: row.url_to_status_code === null || row.url_to_status_code === undefined
        ? null
        : Number(row.url_to_status_code),
      page_from_status: row.page_from_status_code === null || row.page_from_status_code === undefined
        ? null
        : Number(row.page_from_status_code),
      redirect_target: row.url_to_redirect_target ? String(row.url_to_redirect_target) : '',
      is_broken: row.is_broken === true,
      first_seen: String(row.first_seen || ''),
      last_seen: String(row.last_seen || ''),
      page_title: String(row.page_from_title || ''),
      spam_score: Number(row.backlink_spam_score) || 0,
    });
  }
}

const links = [...best.values()].sort((a, b) => b.rank - a.rank);

return [{
  json: {
    failed: false,
    reason: '',
    links,
    returned: items.length,
    unique_domains: links.length,
    total_lost: totalLost,
    window_days: Number(cfg.lost_since_days) || 30,
  },
}];

// A filtering step that can return zero items would end the branch here, and
// the "nothing new" message below would never fire. It always returns exactly
// one item and lets the IF do the routing.
// This node sits downstream of the Data Table read, so the incoming items here
// are the stored rows. Both real sources are read by name instead: the link
// summary from the reader, the watch list from the table.
const summary = $('Read The Lost Links').first().json || {};
const table = $('Read What We Reported').all().map((i) => i.json || {});
const already = new Set(table.map((r) => String(r.link_id || '')).filter(Boolean));

const all = Array.isArray(summary.links) ? summary.links : [];
const fresh = all.filter((l) => !already.has(l.link_id));

const cap = Number($('Settings').first().json.max_to_check) || 12;

return [{
  json: {
    ...summary,
    links: fresh.slice(0, cap),
    fresh_count: fresh.length,
    held_back: Math.max(0, fresh.length - cap),
    already_known: all.length - fresh.length,
  },
}];

const cfg = $('Settings').first().json;
const links = $('One Link Per Loss').all().map((i) => i.json || {});
const checks = $input.all().map((i) => i.json || {});

// The live check runs once per link and n8n keeps them in order, but an HTTP
// node set to continue on error can emit a short array. If the two sides do not
// line up, every row is reported as unchecked rather than paired with somebody
// else's status code.
const aligned = checks.length === links.length;

function liveStatus(index) {
  if (!aligned) return null;
  const res = checks[index] || {};
  const code = Number(res.statusCode);
  return Number.isFinite(code) && code > 0 ? code : null;
}

function dead(code) {
  return code !== null && code >= 400;
}

function redirected(code) {
  return code !== null && code >= 300 && code < 400;
}

const BUCKETS = {
  your_page_gone: {
    order: 1,
    label: 'Your page is gone',
    action: 'Restore the page or redirect it. No email needed.',
  },
  your_redirect: {
    order: 2,
    label: 'You redirected the page',
    action: 'Confirm the redirect still lands somewhere that earns the link.',
  },
  link_removed: {
    order: 3,
    label: 'Link removed, both pages healthy',
    action: 'Worth an email. This is the only bucket that needs one.',
  },
  their_page_gone: {
    order: 4,
    label: 'Their page is gone',
    action: 'Nothing to recover. Logged so it stops coming back.',
  },
  unchecked: {
    order: 5,
    label: 'Could not be checked',
    action: 'The live check did not answer. It will be retried next run.',
  },
};

const rows = links.map((link, i) => {
  const live = liveStatus(i);
  const theirs = link.page_from_status;

  let bucket;
  if (!aligned || live === null) {
    bucket = 'unchecked';
  } else if (dead(live)) {
    bucket = 'your_page_gone';
  } else if (redirected(live) || link.redirect_target) {
    bucket = 'your_redirect';
  } else if (dead(theirs)) {
    bucket = 'their_page_gone';
  } else {
    bucket = 'link_removed';
  }

  const meta = BUCKETS[bucket];
  // Rank is the value of the link; a dofollow link is the one worth the effort.
  // The bucket leads because a page you can fix yourself beats a better link
  // that depends on a stranger answering an email.
  const priority = (10 - meta.order) * 1000 + link.rank * (link.dofollow ? 1 : 0.4);

  return {
    ...link,
    live_status: live,
    bucket,
    bucket_label: meta.label,
    what_to_do: meta.action,
    priority: Math.round(priority),
    needs_outreach: bucket === 'link_removed',
  };
});

rows.sort((a, b) => b.priority - a.priority);

const tally = {};
for (const r of rows) tally[r.bucket] = (tally[r.bucket] || 0) + 1;

const outreach = rows.filter((r) => r.needs_outreach).slice(0, Number(cfg.max_angles) || 5);

return [{
  json: {
    rows,
    tally,
    aligned,
    outreach_brief: outreach
      .map((r, i) => `${i + 1}. ${r.domain_from} linked to ${r.url_to} with the anchor "${r.anchor || '(image or bare link)'}" from the page "${r.page_title || r.url_from}". The link is gone; both pages still load.`)
      .join('\n'),
    outreach_count: outreach.length,
  },
}];

// This node sits downstream of the model, so the incoming items here are the
// chain's text. The sorter is read by name instead: it emits one object
// holding every row.
const sorted = $('Sort Into Recovery Buckets').first().json || {};
const summary = $('Drop The Ones We Sent').first().json || {};
const cfg = $('Settings').first().json;
const rows = Array.isArray(sorted.rows) ? sorted.rows : [];
const tally = sorted.tally || {};

let angles = '';
try {
  angles = String(($('Write The Outreach Angles').first().json || {}).text || '');
} catch (e) {
  angles = '';
}

// The model is asked for "1. ..." lines and sometimes returns prose. Anything
// that does not start with a number is dropped rather than smeared across the
// wrong domain.
const angleFor = new Map();
const outreachRows = rows.filter((r) => r.needs_outreach);
for (const line of angles.split('\n')) {
  const m = line.match(/^\s*(\d+)[.)]\s*(.+)$/);
  if (!m) continue;
  const idx = Number(m[1]) - 1;
  if (outreachRows[idx]) angleFor.set(outreachRows[idx].link_id, m[2].trim());
}

function plural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

const ORDER = ['your_page_gone', 'your_redirect', 'link_removed', 'their_page_gone', 'unchecked'];
const LABEL = {
  your_page_gone: 'Your page is gone - fix on your side',
  your_redirect: 'You redirected it - check where it lands',
  link_removed: 'Removed while both pages are healthy - worth an email',
  their_page_gone: 'Their page is gone - nothing to recover',
  unchecked: 'Could not be checked this run',
};

const lines = [];
lines.push(`*Lost backlinks for ${cfg.domain}* - ${plural(summary.fresh_count || 0, 'new loss', 'new losses')} in the last ${summary.window_days} days`);
lines.push(`${summary.total_lost} lost links on record; ${summary.unique_domains} distinct domains in this pull, ${rows.length} triaged below.`);
if (summary.held_back > 0) {
  lines.push(`_${summary.held_back} more were held back by the per-run cap and will come round next time._`);
}
if (summary.already_known > 0) {
  lines.push(`_${summary.already_known} were reported before and are not repeated._`);
}
if (sorted.aligned === false) {
  lines.push('_The live page check did not line up with the link list this run, so every row is marked unchecked rather than guessed at._');
}
lines.push('');

for (const bucket of ORDER) {
  const inBucket = rows.filter((r) => r.bucket === bucket);
  if (!inBucket.length) continue;
  lines.push(`*${LABEL[bucket]}* (${inBucket.length})`);
  for (const r of inBucket.slice(0, 6)) {
    const angle = angleFor.get(r.link_id);
    const follow = r.dofollow ? 'dofollow' : 'nofollow';
    lines.push(`• ${r.domain_from} -> ${r.url_to} | rank ${r.rank}, ${follow}${r.live_status ? `, your page now ${r.live_status}` : ''}`);
    if (angle) lines.push(`    angle: ${angle}`);
  }
  if (inBucket.length > 6) lines.push(`    _and ${inBucket.length - 6} more in the sheet_`);
  lines.push('');
}

const sheetRows = rows.map((r) => ({
  checked_on: new Date().toISOString().slice(0, 10),
  domain_from: r.domain_from,
  url_from: r.url_from,
  url_to: r.url_to,
  anchor: r.anchor,
  bucket: r.bucket_label,
  what_to_do: r.what_to_do,
  outreach_angle: angleFor.get(r.link_id) || '',
  rank: r.rank,
  domain_rank: r.domain_rank,
  dofollow: r.dofollow ? 'yes' : 'no',
  link_type: r.item_type,
  your_page_status_now: r.live_status === null ? 'not checked' : r.live_status,
  their_page_status_crawled: r.page_from_status === null ? 'unknown' : r.page_from_status,
  first_seen: r.first_seen,
  last_seen: r.last_seen,
  priority: r.priority,
}));

// One item per row so the Sheets append writes one row per link. Returned as a
// single object with a rows array, the append would write one row whose columns
// were "message" and "rows".
return [{ json: { message: lines.join('\n'), rows: sheetRows, row_count: sheetRows.length } }];

// Every triaged link is written back so next Monday hands you the ones you have
// not seen. This hangs beside the report rather than in front of it: a Data
// Table write emits the row it stored, not the item it was given.
const rows = ($input.all() || []).map((i) => i.json || {});
const first = rows[0] || {};
const list = Array.isArray(first.rows) ? first.rows : [];
return list.map((r) => ({ json: { link_id: `${r.domain_from}|${r.url_to}`, bucket: r.bucket, seen_on: r.checked_on } }));
